import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { migrationJournalSchema } from './pglite-database';

describe('reading the drizzle migration journal', () => {
	// The producer, not a literal written beside the reader: the journal this
	// parses is generated by drizzle-kit, and a schema that only ever meets its
	// author's own fixture is the TN-14 failure mode.
	it('accepts the journal drizzle-kit actually wrote', async () => {
		const path = fileURLToPath(new URL('../../../drizzle/meta/_journal.json', import.meta.url));
		const journal: unknown = JSON.parse(await readFile(path, 'utf8'));
		expect(migrationJournalSchema.parse(journal).entries.length).toBeGreaterThan(0);
	});

	it('keeps a per-entry field it does not read', () => {
		const parsed = migrationJournalSchema.parse({
			version: '7',
			dialect: 'postgresql',
			entries: [{ idx: 0, version: '7', when: 1, tag: '0000_init', breakpoints: true }]
		});
		expect(parsed.entries[0]?.tag).toBe('0000_init');
	});

	it('refuses a journal with no entry list', () => {
		expect(() => migrationJournalSchema.parse({ version: '7', dialect: 'postgresql' })).toThrow();
	});

	it('refuses an entry with no tag to load SQL by', () => {
		expect(() => migrationJournalSchema.parse({ entries: [{ idx: 0 }] })).toThrow();
	});
});
